'use client';

import {useCallback,useEffect,useMemo,useRef,useState,type ChangeEvent,type FormEvent,type ReactNode} from 'react';

type Mode='bmail'|'bazmeet'|'calendar'|'contacts';
type Item={id:string;title:string;body?:string;content?:string;createdAt?:string;updatedAt?:string;meta?:Record<string,unknown>};
type IconKey='menu'|'search'|'plus'|'mail'|'star'|'clock'|'send'|'draft'|'trash'|'refresh'|'settings'|'apps'|'calendar'|'video'|'contacts'|'archive'|'spam'|'tag'|'chevron'|'left'|'right'|'close'|'copy'|'download'|'edit'|'phone'|'location'|'shield'|'more'|'inbox'|'users'|'mic'|'screen'|'hand'|'poll'|'qna'|'record'|'bell'|'task'|'focus'|'briefcase'|'upload'|'camera';

type MailFolder='INBOX'|'STARRED'|'SNOOZED'|'SENT'|'DRAFTS'|'SCHEDULED'|'ARCHIVE'|'SPAM'|'TRASH';
type MailMeta={folder:MailFolder;to:string[];cc:string[];bcc:string[];labels:string[];starred:boolean;read:boolean;important:boolean;snoozedUntil:string;scheduledFor:string;sentAt:string;from:string;attachments:{name:string;size:number;type:string}[];category:'PRIMARY'|'PROMOTIONS'|'SOCIAL'|'UPDATES';confidential:boolean;expiresAt:string;allowForward:boolean;priority:'normal'|'high'|'low';threadId:string};
type MeetMeta={start:string;end:string;guests:string[];cohosts:string[];meetingCode:string;waitingRoom:boolean;chatEnabled:boolean;captionsEnabled:boolean;recordingConsent:boolean;hostApproval:boolean;layout:'auto'|'tiled'|'spotlight'|'sidebar';roomStatus:'SCHEDULED'|'LIVE'|'ENDED';notes:string;timezone:string;allowScreenShare:boolean;allowReactions:boolean;allowPolls:boolean;allowQna:boolean;breakoutCount:number;transcriptionEnabled:boolean;attendanceTracking:boolean;joinPolicy:'invited'|'anyone-with-link'|'organization';noiseSuppression:boolean};
type CalendarEvent={_bz9:'event';kind:'event'|'task'|'focus'|'ooo'|'appointment';start:string;end:string;location:string;notes:string;allDay:boolean;timezone:string;guests:string[];recurrence:string;reminders:number[];availability:'busy'|'free';color:string;meetingUrl:string;guestCanInvite:boolean;guestCanModify:boolean;autoDecline:boolean;booking?:{duration:number;buffer:number;maxPerDay:number;leadMinutes:number;cohosts:string[]}};
type ContactMeta={_bz9:'contact';email:string;phone:string;organization:string;notes:string;emails:string[];phones:string[];jobTitle:string;department:string;birthday:string;address:string;website:string;labels:string[];relationship:string;company:string};
type MailPreferences={signature:string;undoSendSeconds:number;defaultFrom:string;defaultLabels:string[]};

const APP_PORTS={workspace:3021,bmail:3036,bazmeet:3037,calendar:3028,contacts:3029,bazchat:3013,bicord:3017};
const MAIL_FOLDERS:MailFolder[]=['INBOX','STARRED','SNOOZED','SENT','DRAFTS','SCHEDULED','ARCHIVE','SPAM','TRASH'];
const split=(value:string)=>value.split(/[;,\n]/).map(x=>x.trim()).filter(Boolean);
const join=(value:string[]|undefined)=>Array.isArray(value)?value.join(', '):'';
const isoLocal=(value:string|undefined)=>{if(!value)return '';const d=new Date(value);if(Number.isNaN(+d))return '';const p=(n:number)=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`};
const toIso=(value:string)=>value?new Date(value).toISOString():'';
const content=(i:Item)=>i.body??i.content??'';
const when=(value?:string)=>{if(!value)return '';const d=new Date(value);return Number.isNaN(+d)?'':d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})};
const parse=<T,>(raw:string|undefined):T|null=>{try{return raw?JSON.parse(raw) as T:null}catch{return null}};
const download=(name:string,text:string,type:string)=>{const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1200)};

function Icon({name,size=20}:{name:IconKey;size?:number}){
 const p:Record<IconKey,ReactNode>={
  menu:<path d="M4 7h16M4 12h16M4 17h16"/>, search:<><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></>, plus:<path d="M12 4v16M4 12h16"/>, mail:<><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/></>, star:<path d="m12 2.8 2.9 5.9 6.5.9-4.7 4.6 1.1 6.5-5.8-3.1-5.8 3.1 1.1-6.5-4.7-4.6 6.5-.9z"/>, clock:<><circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/></>, send:<path d="m3 4 18 8-18 8 3-8zM6 12h10"/>, draft:<><path d="M6 3h9l4 4v14H6zM14 3v5h5M9 13h7M9 16h5"/></>, trash:<><path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14M10 11v6M14 11v6"/></>, refresh:<><path d="M20 8a8 8 0 0 0-14-3L4 8M4 3v5h5M4 16a8 8 0 0 0 14 3l2-3M20 21v-5h-5"/></>, settings:<><circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9 7 7M17 17l2.1 2.1M19.1 4.9 17 7M7 17l-2.1 2.1"/></>, apps:<path d="M4 4h4v4H4zM10 4h4v4h-4zM16 4h4v4h-4zM4 10h4v4H4zM10 10h4v4h-4zM16 10h4v4h-4zM4 16h4v4H4zM10 16h4v4h-4zM16 16h4v4h-4z"/>, calendar:<><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 10h18"/></>, video:<><rect x="3" y="6" width="13" height="12" rx="2"/><path d="m16 10 5-3v10l-5-3z"/></>, contacts:<><circle cx="9" cy="8" r="3.5"/><path d="M3 20c0-4 2-6 6-6s6 2 6 6M17 8h5M17 12h5M17 16h5"/></>, archive:<><path d="M4 7h16v14H4zM3 3h18v4H3zM9 11h6"/></>, spam:<><path d="m8 3-5 5v8l5 5h8l5-5V8l-5-5zM12 7v6M12 17h.01"/></>, tag:<path d="M3 12V4h8l10 10-7 7zM7 8h.01"/>, chevron:<path d="m9 5 7 7-7 7"/>, left:<path d="m15 5-7 7 7 7"/>, right:<path d="m9 5 7 7-7 7"/>, close:<path d="M5 5 19 19M19 5 5 19"/>, copy:<><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4H4v12h4"/></>, download:<><path d="M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3"/></>, edit:<><path d="M3 21h5L21 8l-5-5L3 16zM13 6l5 5"/></>, phone:<path d="M6 3H3v5c2 6 7 11 13 13h5v-4l-5-3-3 3a16 16 0 0 1-6-6l3-3z"/>, location:<><path d="M12 22S5 14 5 10a7 7 0 1 1 14 0c0 4-7 12-7 12"/><circle cx="12" cy="10" r="2"/></>, shield:<><path d="m12 2 8 4v6c0 5-4 8-8 10-4-2-8-5-8-10V6z"/><path d="m9 12 2 2 4-4"/></>, more:<path d="M5 12h.01M12 12h.01M19 12h.01"/>, inbox:<><path d="M4 4h16v16H4z"/><path d="M4 14h5l2 3h2l2-3h5"/></>, users:<><path d="M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21c0-5 2-7 6-7s6 2 6 7M17 11a3 3 0 1 0 0-6M16 14c4 0 6 2 6 7"/></>, mic:<><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v4"/></>, screen:<><rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8M12 17v4"/></>, hand:<path d="M6 11V6a2 2 0 1 1 4 0v4-6a2 2 0 1 1 4 0v6-4a2 2 0 1 1 4 0v6-2a2 2 0 1 1 4 0v5c0 4-3 7-7 7h-2c-3 0-5-1-7-4l-3-4a2 2 0 0 1 3-3z"/>, poll:<><path d="M5 19V9M12 19V4M19 19v-7"/></>, qna:<><circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.8 2.8 0 1 1 4.2 2.4c-1 .6-1.7 1.1-1.7 2.6M12 17h.01"/></>, record:<><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/></>, bell:<><path d="M6 9a6 6 0 0 1 12 0v5l2 3H4l2-3zM9 21h6"/></>, task:<><rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 9 2 2 4-4M8 15h8"/></>, focus:<><circle cx="12" cy="12" r="4"/><path d="M3 9V3h6M15 3h6v6M21 15v6h-6M9 21H3v-6"/></>, briefcase:<><rect x="3" y="7" width="18" height="13" rx="2"/><path d="M9 7V4h6v3M3 12h18"/></>, upload:<><path d="M12 21V9m-5 5 5-5 5 5M4 5h16"/></>, camera:<><rect x="3" y="6" width="18" height="14" rx="2"/><path d="m7 6 2-3h6l2 3"/><circle cx="12" cy="13" r="3"/></>
 };
 return <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">{p[name]}</svg>
}

async function json<T=unknown>(url:string,init?:RequestInit):Promise<T>{const r=await fetch(url,{credentials:'same-origin',...init,headers:{...(init?.body?{'content-type':'application/json'}:{}),...(init?.headers||{})}});let b:any={};try{b=await r.json()}catch{}if(!r.ok)throw new Error(b?.message||b?.error||`Request failed (${r.status})`);return b as T}

function appUrl(port:number){return `http://localhost:${port}/`}

function Modal({title,close,children,wide=false}:{title:string;close:()=>void;children:ReactNode;wide?:boolean}){const r=useRef<HTMLDivElement|null>(null);useEffect(()=>{const old=document.activeElement as HTMLElement|null;r.current?.focus();const k=(e:KeyboardEvent)=>{if(e.key==='Escape')close()};document.addEventListener('keydown',k);return()=>{document.removeEventListener('keydown',k);old?.focus()}},[close]);return <div className="bx-modalveil" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div className={`bx-dialog ${wide?'bx-v3-wide':''}`} role="dialog" aria-modal="true" tabIndex={-1} ref={r}><header><h2>{title}</h2><button aria-label="Close" onClick={close}><Icon name="close"/></button></header>{children}</div></div>}
function Empty({icon,title,text}:{icon:IconKey;title:string;text:string}){return <div className="bx-empty"><span><Icon name={icon} size={34}/></span><h3>{title}</h3><p>{text}</p></div>}
function Status({error,notice,clear}:{error:string;notice:string;clear:()=>void}){return <>{error&&<div className="bx-alert" role="alert">{error}<button onClick={clear}>×</button></div>}{notice&&<div className="bx-ok" role="status">{notice}<button onClick={clear}>×</button></div>}</>}

function Shell({mode,query,setQuery,children,primaryAction}:{mode:Mode;query:string;setQuery:(v:string)=>void;children:ReactNode;primaryAction?:()=>void}){
 const [nav,setNav]=useState(false),[apps,setApps]=useState(false);
 const title=mode==='bmail'?'Bmail':mode==='bazmeet'?'BazMeet':mode==='calendar'?'Calendar':'Contacts';
 const placeholder=mode==='bmail'?'Search mail — try from:, to:, label:, is:unread':mode==='bazmeet'?'Search meetings':mode==='calendar'?'Search events and schedules':'Search people, companies and labels';
 return <div className="bx-shell bx-v3-shell"><header className="bx-top"><button className="bx-iconbtn bx-hamburger" aria-label="Toggle navigation" onClick={()=>setNav(v=>!v)}><Icon name="menu"/></button><a className="bx-logo" href="/"><img src="/bazaara-v9-symbol.svg" alt=""/><span>{title}</span></a><label className="bx-search"><Icon name="search" size={21}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={placeholder}/>{query&&<button onClick={()=>setQuery('')} aria-label="Clear search"><Icon name="close" size={17}/></button>}</label><div className="bx-toptools"><span className="bx-system-status"><Icon name="shield" size={17}/> BAZAARA</span><a className="bx-iconbtn" href={appUrl(APP_PORTS.workspace)} aria-label="Workspace"><Icon name="apps"/></a><button className="bx-iconbtn" aria-label="Open apps" onClick={()=>setApps(v=>!v)}><Icon name="more"/></button><span className="bx-avatar">B</span></div>{apps&&<div className="bx-launcher bx-v3-launcher"><strong>Communication</strong><div className="bx-launch-grid">{[['Bmail',APP_PORTS.bmail,'mail'],['BazMeet',APP_PORTS.bazmeet,'video'],['Calendar',APP_PORTS.calendar,'calendar'],['Contacts',APP_PORTS.contacts,'contacts'],['BChat',APP_PORTS.bazchat,'mail'],['Bicord',APP_PORTS.bicord,'users']].map(([n,p,i])=><a key={String(n)} href={appUrl(Number(p))}><span><Icon name={i as IconKey}/></span>{n}</a>)}</div></div>}</header><div className={`bx-v3-mobilebar ${nav?'open':''}`}>{primaryAction&&<button className="bx-action" onClick={primaryAction}><Icon name="plus"/> New</button>}</div>{children}</div>
}

function safeMail(i:Item):MailMeta{const m=(i.meta||{}) as Partial<MailMeta>;const f=MAIL_FOLDERS.includes(m.folder as MailFolder)?m.folder as MailFolder:'DRAFTS';return {folder:f,to:Array.isArray(m.to)?m.to:[],cc:Array.isArray(m.cc)?m.cc:[],bcc:Array.isArray(m.bcc)?m.bcc:[],labels:Array.isArray(m.labels)?m.labels:[],starred:Boolean(m.starred),read:m.read!==false,important:Boolean(m.important),snoozedUntil:typeof m.snoozedUntil==='string'?m.snoozedUntil:'',scheduledFor:typeof m.scheduledFor==='string'?m.scheduledFor:'',sentAt:typeof m.sentAt==='string'?m.sentAt:'',from:typeof m.from==='string'?m.from:'',attachments:Array.isArray(m.attachments)?m.attachments:[],category:['PRIMARY','PROMOTIONS','SOCIAL','UPDATES'].includes(String(m.category))?m.category as MailMeta['category']:'PRIMARY',confidential:Boolean(m.confidential),expiresAt:typeof m.expiresAt==='string'?m.expiresAt:'',allowForward:m.allowForward!==false,priority:['normal','high','low'].includes(String(m.priority))?m.priority as MailMeta['priority']:'normal',threadId:typeof m.threadId==='string'?m.threadId:''}}
function mailQuery(i:Item,q:string){const m=safeMail(i);const terms=q.trim().split(/\s+/).filter(Boolean);if(!terms.length)return true;const hay=`${i.title} ${content(i)} ${m.from} ${m.to.join(' ')} ${m.cc.join(' ')} ${m.labels.join(' ')}`.toLowerCase();return terms.every(t=>{const [k,...rest]=t.split(':');const v=rest.join(':').toLowerCase();if(rest.length){if(k==='from')return m.from.toLowerCase().includes(v);if(k==='to')return m.to.join(' ').toLowerCase().includes(v);if(k==='label')return m.labels.some(x=>x.toLowerCase().includes(v));if(k==='is')return v==='unread'?!m.read:v==='starred'?m.starred:v==='important'?m.important:true;if(k==='category')return m.category.toLowerCase()===v;}return hay.includes(t.toLowerCase())})}

function Bmail({query,setQuery}:{query:string;setQuery:(v:string)=>void}){
 const [items,setItems]=useState<Item[]>([]),[folder,setFolder]=useState<MailFolder>('INBOX'),[category,setCategory]=useState<MailMeta['category']>('PRIMARY'),[selected,setSelected]=useState(''),[compose,setCompose]=useState(false),[composeTo,setComposeTo]=useState(''),[settings,setSettings]=useState(false),[prefs,setPrefs]=useState<MailPreferences>({signature:'',undoSendSeconds:5,defaultFrom:'',defaultLabels:[]}),[cap,setCap]=useState<Record<string,unknown>>({}),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[undo,setUndo]=useState<{id:string;timer:number}|null>(null);
 const load=useCallback(async()=>{try{const [r,p,c]=await Promise.all([json<{items:Item[]}>('/api/items'),json<{preferences:MailPreferences}>('/api/preferences').catch(()=>({preferences:prefs})),json<Record<string,unknown>>('/api/capabilities').catch(()=>({}))]);setItems(r.items);setPrefs(p.preferences);setCap(c)}catch(e){setError(e instanceof Error?e.message:'Could not load Bmail.')}},[]);useEffect(()=>{void load();if(typeof window!=='undefined'){const to=new URLSearchParams(window.location.search).get('to');if(to){setComposeTo(to);setCompose(true)}}},[load]);
 const rows=useMemo(()=>items.filter(i=>{const m=safeMail(i);const folderOk=folder==='STARRED'?m.starred:m.folder===folder;const catOk=folder!=='INBOX'||m.category===category;return folderOk&&catOk&&mailQuery(i,query)}),[items,folder,category,query]);const active=items.find(i=>i.id===selected)||null;
 const counts=useMemo(()=>Object.fromEntries(MAIL_FOLDERS.map(f=>[f,items.filter(i=>f==='STARRED'?safeMail(i).starred:safeMail(i).folder===f).length])) as Record<MailFolder,number>,[items]);
 async function update(i:Item,meta:Partial<MailMeta>,body?:string,title?:string){const next={...safeMail(i),...meta};await json(`/api/items/${encodeURIComponent(i.id)}`,{method:'PUT',body:JSON.stringify({title:title??i.title,body:body??content(i),meta:next})});await load()}
 async function remove(i:Item){await update(i,{folder:'TRASH'});if(selected===i.id)setSelected('')}
 async function sendNow(i:Item){if(undo){clearTimeout(undo.timer);setUndo(null)};const seconds=Math.max(0,Math.min(30,prefs.undoSendSeconds||0));if(seconds>0){setNotice(`Send queued for ${seconds} seconds. Undo is available.`);const timer=window.setTimeout(async()=>{setUndo(null);try{await json(`/api/items/${encodeURIComponent(i.id)}/send`,{method:'POST',body:'{}'});setNotice('Message sent.');await load()}catch(e){setError(e instanceof Error?e.message:'Send failed.')}},seconds*1000);setUndo({id:i.id,timer});return}await json(`/api/items/${encodeURIComponent(i.id)}/send`,{method:'POST',body:'{}'});setNotice('Message sent.');await load()}
 function undoSend(){if(!undo)return;clearTimeout(undo.timer);setUndo(null);setNotice('Send cancelled. Message remains a draft.')}
 return <Shell mode="bmail" query={query} setQuery={setQuery} primaryAction={()=>{setComposeTo('');setCompose(true)}}><div className="bx-body"><aside className="bx-sidebar"><button className="bx-primary" onClick={()=>{setComposeTo('');setCompose(true)}}><Icon name="plus"/> Compose</button><nav>{([['INBOX','Inbox','inbox'],['STARRED','Starred','star'],['SNOOZED','Snoozed','clock'],['SENT','Sent','send'],['DRAFTS','Drafts','draft'],['SCHEDULED','Scheduled','clock'],['ARCHIVE','Archive','archive'],['SPAM','Spam','spam'],['TRASH','Trash','trash']] as [MailFolder,string,IconKey][]).map(([f,l,ic])=><button key={f} className={folder===f?'bx-active':''} onClick={()=>{setFolder(f);setSelected('')}}><Icon name={ic}/><span>{l}</span><small>{counts[f]}</small></button>)}</nav><div className="bx-divider"/><button className="bx-v3-sideaction" onClick={()=>setSettings(true)}><Icon name="settings"/> Mail settings</button><small className="bx-v3-cap">Delivery: {cap.deliveryConfigured?'configured':'adapter required'}</small></aside><main className="bx-main bx-v3-mailmain"><Status error={error} notice={notice} clear={()=>{setError('');setNotice('')}}/>{undo&&<div className="bx-v3-undo">Message queued for sending. <button onClick={undoSend}>Undo send</button></div>}<section className="bx-mailframe bx-v3-mailframe"><div className="bx-mailtools"><button onClick={()=>void load()} aria-label="Refresh"><Icon name="refresh"/></button><strong>{folder[0]+folder.slice(1).toLowerCase()}</strong><span className="bx-v3-grow"/><button onClick={()=>setQuery('is:unread')}>Unread</button><button onClick={()=>setQuery('is:important')}>Important</button><small>{rows.length} items</small></div>{folder==='INBOX'&&<div className="bx-mailtabs">{(['PRIMARY','PROMOTIONS','SOCIAL','UPDATES'] as const).map(c=><button key={c} className={category===c?'bx-currenttab':''} onClick={()=>setCategory(c)}>{c[0]+c.slice(1).toLowerCase()}</button>)}</div>}<div className="bx-v3-mailgrid"><div className="bx-messages">{rows.length?rows.map(i=>{const m=safeMail(i);return <div key={i.id} className={`bx-message ${!m.read?'bx-mail-unread':''} ${selected===i.id?'bx-v3-selected':''}`}><button className={m.starred?'bx-fav':''} onClick={()=>void update(i,{starred:!m.starred})} aria-label="Star"><Icon name="star"/></button><button className="bx-message-main" onClick={()=>{setSelected(i.id);if(!m.read)void update(i,{read:true})}}><strong>{m.from||m.to.join(', ')||'Draft'}</strong><span><b>{i.title}</b> — {content(i).slice(0,110)}</span></button>{m.important&&<span className="bx-v3-priority">!</span>}<time>{when(i.updatedAt||i.createdAt)}</time><button onClick={()=>void remove(i)}><Icon name="trash" size={17}/></button></div>}):<Empty icon="mail" title="Nothing here" text="Messages matching this mailbox view will appear here."/>}</div><aside className="bx-v3-reading">{active?<MailReading item={active} meta={safeMail(active)} update={update} sendNow={sendNow} close={()=>setSelected('')}/>:<Empty icon="inbox" title="Select a message" text="Open a message to read it and use archive, snooze, labels, spam, delete and delivery actions."/>}</aside></div></section></main></div>{compose&&<MailCompose initialTo={composeTo} prefs={prefs} close={()=>setCompose(false)} saved={async(i,send)=>{setCompose(false);await load();if(send)await sendNow(i)}} setError={setError}/>} {settings&&<MailSettings prefs={prefs} close={()=>setSettings(false)} saved={async p=>{setPrefs(p);await load();setSettings(false);setNotice('Mail settings saved.')}}/>}</Shell>
}

